import { expect } from '@playwright/test';

// Compare the rendered answer against Chromium's native text shaping, not a
// saved image generated by the PDF renderer itself.
export async function expectArabicDocumentShape(page, capture, selector = '.ql-arabic-wrap-regression') {
  const previews = await page.locator('.document-answer-preview__pages img')
    .evaluateAll(images => images.map(image => ({ url: image.src, height: image.naturalHeight / 1.5 })));
  const bounds = await page.evaluate(selector => {
    const source = window.documentNativeSource;
    source.id = 'document-native-reference';
    Object.assign(source.style, { left: '0', top: '0', zIndex: '2147483647' });
    document.querySelector('dialog[open]').appendChild(source);
    const root = source.querySelector('.rich-text-document-view__page').getBoundingClientRect();
    const target = source.querySelector(selector).getBoundingClientRect();
    // Keep the reference cell in the mobile viewport without resizing its table.
    source.style.left = `${-target.x}px`;
    source.style.top = `${-target.y}px`;
    return { x: target.x - root.x, y: target.y - root.y, width: target.width, height: target.height };
  }, selector);
  let offset = 0;
  const preview = previews.find(image => {
    if (bounds.y < offset + image.height) return true;
    offset += image.height;
    return false;
  });
  expect(preview, 'The complete answer must be included in the PDF pages').toBeTruthy();
  bounds.y -= offset;
  const previewUrl = preview.url;
  const reference = await page.locator('#document-native-reference').locator(selector).screenshot();
  const comparison = await page.evaluate(async ({ reference, previewUrl, bounds }) => {
    const load = async src => { const image = new Image(); image.src = src; await image.decode(); return image; };
    const [native, preview] = await Promise.all([load(reference), load(previewUrl)]);
    const canvas = document.createElement('canvas');
    canvas.width = native.width; canvas.height = native.height;
    const context = canvas.getContext('2d');
    context.drawImage(native, 0, 0);
    const expected = context.getImageData(0, 0, canvas.width, canvas.height).data;
    let best = 1;
    let closest;
    for (let dx = -2; dx <= 2; dx++) for (let dy = -2; dy <= 2; dy++) {
      context.fillStyle = '#fff'; context.fillRect(0, 0, canvas.width, canvas.height);
      context.drawImage(preview, bounds.x * 1.5 + dx, bounds.y * 1.5 + dy, canvas.width, canvas.height,
        0, 0, canvas.width, canvas.height);
      const actual = context.getImageData(0, 0, canvas.width, canvas.height).data;
      let mismatch = 0;
      for (let i = 0; i < expected.length; i += 4) {
        if (Math.abs(expected[i] - actual[i]) > 80) mismatch++;
      }
      const difference = mismatch / (canvas.width * canvas.height);
      if (difference < best) { best = difference; closest = canvas.toDataURL(); }
    }
    return { difference: best, actual: closest };
  }, { reference: `data:image/png;base64,${reference.toString('base64')}`, previewUrl, bounds });
  await page.locator('#document-native-reference').evaluate(element => element.remove());
  capture?.({ ...comparison, reference });
  expect(comparison.difference, 'Wrapped Arabic must match native connected glyphs').toBeLessThan(0.06);
}
